    prismP(ws, rectP(-9.2, 8.9, 11.1, 13.95), G0 + 7.1, G0 + 7.7); prismP(ws2, rectP(-9.35, 9.05, 11.1, 14.1), G0 + 7.7, G0 + 7.95);
    for (let x = -9.0; x <= 8.8; x += 0.55) boxP(ws, 0.16, 0.9, 0.16, x, G0 + 7.95, 13.9, 0);
    segP(ws, [-9.2, G0 + 8.95, 13.9], [8.9, G0 + 8.95, 13.9], 0.15, 4);
